create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name','')); insert into public.watchlists(owner_id,name) values(new.id,'My extensions'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.is_team_member(target_team uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.team_members where team_id=target_team and user_id=auth.uid()) $$;
alter table public.extensions enable row level security; alter table public.extension_versions enable row level security; alter table public.scan_jobs enable row level security; alter table public.scans enable row level security; alter table public.findings enable row level security; alter table public.artifact_files enable row level security; alter table public.dependencies enable row level security; alter table public.profiles enable row level security; alter table public.watchlists enable row level security; alter table public.watchlist_items enable row level security; alter table public.teams enable row level security; alter table public.team_members enable row level security; alter table public.team_invitations enable row level security; alter table public.team_watchlist_items enable row level security; alter table public.finding_triage enable row level security; alter table public.finding_comments enable row level security; alter table public.product_events enable row level security; alter table public.design_partner_leads enable row level security;
create policy "public catalog" on public.extensions for select to anon,authenticated using(true); create policy "public versions" on public.extension_versions for select to anon,authenticated using(true); create policy "public scans" on public.scans for select to anon,authenticated using(true); create policy "public findings" on public.findings for select to anon,authenticated using(true); create policy "public files" on public.artifact_files for select to anon,authenticated using(true); create policy "public dependencies" on public.dependencies for select to anon,authenticated using(true);
create policy "own profile" on public.profiles for all to authenticated using((select auth.uid())=id) with check((select auth.uid())=id); create policy "own watchlists" on public.watchlists for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id); create policy "own watchlist items" on public.watchlist_items for all to authenticated using(exists(select 1 from public.watchlists w where w.id=watchlist_id and w.owner_id=(select auth.uid()))) with check(exists(select 1 from public.watchlists w where w.id=watchlist_id and w.owner_id=(select auth.uid())));
create policy "team access" on public.teams for select to authenticated using(public.is_team_member(id)); create policy "team members access" on public.team_members for select to authenticated using(public.is_team_member(team_id)); create policy "team invitations access" on public.team_invitations for all to authenticated using(public.is_team_member(team_id)) with check(public.is_team_member(team_id)); create policy "team watchlist access" on public.team_watchlist_items for all to authenticated using(public.is_team_member(team_id)) with check(public.is_team_member(team_id)); create policy "team triage access" on public.finding_triage for all to authenticated using(public.is_team_member(team_id)) with check(public.is_team_member(team_id)); create policy "team comments access" on public.finding_comments for all to authenticated using(public.is_team_member(team_id)) with check(public.is_team_member(team_id)); create policy "own events readable" on public.product_events for select to authenticated using((select auth.uid())=user_id); create policy "own leads readable" on public.design_partner_leads for select to authenticated using((select auth.uid())=user_id);
create index extensions_catalog_rank on public.extensions(catalog_rank nulls last); create index versions_published on public.extension_versions(extension_id,published_at desc); create index scans_extension_version on public.scans(extension_id,version,scanned_at desc); create index findings_scan_action on public.findings(scan_id,actionability,severity); create index product_events_name_created on public.product_events(name,created_at desc); create index design_partner_leads_created on public.design_partner_leads(created_at desc);;
